class Solution {
  public int[] findMedian(int n, int[][] edges, int[][] queries) {
    int[] start = new int[n + 1];
    for (int[] e : edges) {
      start[e[0] + 1]++;
      start[e[1] + 1]++;
    }
    for (int i = 0; i < n; i++) start[i + 1] += start[i];
    int[] fill = new int[n], to = new int[2 * (n - 1)], w = new int[2 * (n - 1)];
    for (int[] e : edges) {
      int p = start[e[0]] + fill[e[0]]++;
      to[p] = e[1];
      w[p] = e[2];
      p = start[e[1]] + fill[e[1]]++;
      to[p] = e[0];
      w[p] = e[2];
    }
    int LOG = 1;
    while ((1 << LOG) < n) LOG++;
    int[][] up = new int[LOG + 1][n];
    int[] depth = new int[n], queue = new int[n];
    long[] dist = new long[n];
    boolean[] seen = new boolean[n];
    int head = 0, tail = 0;
    queue[tail++] = 0;
    seen[0] = true;
    while (head < tail) {
      int u = queue[head++];
      for (int p = start[u]; p < start[u + 1]; p++) {
        int v = to[p];
        if (seen[v]) continue;
        seen[v] = true;
        up[0][v] = u;
        depth[v] = depth[u] + 1;
        dist[v] = dist[u] + w[p];
        queue[tail++] = v;
      }
    }
    for (int l = 1; l <= LOG; l++) for (int i = 0; i < n; i++) up[l][i] = up[l - 1][up[l - 1][i]];
    int[] ans = new int[queries.length];
    for (int qi = 0; qi < queries.length; qi++) {
      int u = queries[qi][0], v = queries[qi][1];
      int a = u, b = v;
      if (depth[a] < depth[b]) {
        int t = a;
        a = b;
        b = t;
      }
      for (int l = 0; l <= LOG; l++) if (((depth[a] - depth[b]) >> l & 1) != 0) a = up[l][a];
      if (a != b) {
        for (int l = LOG; l >= 0; l--) {
          if (up[l][a] != up[l][b]) {
            a = up[l][a];
            b = up[l][b];
          }
        }
        a = up[0][a];
      }
      int lca = a;
      long total = dist[u] + dist[v] - 2 * dist[lca];
      if (total == 0) {
        ans[qi] = u;
      } else if (2 * (dist[u] - dist[lca]) >= total) {
        int cur = u;
        for (int l = LOG; l >= 0; l--) {
          int anc = up[l][cur];
          if (depth[anc] >= depth[lca] && 2 * (dist[u] - dist[anc]) < total) cur = anc;
        }
        ans[qi] = up[0][cur];
      } else {
        int cur = v;
        for (int l = LOG; l >= 0; l--) {
          int anc = up[l][cur];
          if (depth[anc] > depth[lca] && 2 * (dist[u] + dist[anc] - 2 * dist[lca]) >= total)
            cur = anc;
        }
        ans[qi] = cur;
      }
    }
    return ans;
  }
}
